"""FM-16G original six-tier pathways, with provisional editorial demand."""
import sympy as s
from calibration_bank import LEVELS,L
M=s.Matrix
k,h,t,u,x,y,z=s.symbols('k h t u x y z',real=True)
PATHS={'matrix-conformability':'MAT.arithmetic.dimensions','singular-condition':'MAT.singular.condition','line-intersection':'VEC.intersections.line-line','unit-vector':'VEC.3d.unit'}
RATIONALES={
'matrix-conformability':['Interpret rows and columns.','Distinguish equal-size addition from compatible multiplication.','Determine admissible operations and output sizes.','Infer dimensions from a chain with two constraints.','Reconstruct dimensions from compatible and incompatible operations.','Prove and classify dimension quadruples from product, sum and nonconformability conditions.'],
'singular-condition':['Solve a factored quadratic equation.','Identify a determinant misconception.','Find all singular parameter values.','Combine determinant conditions for two related matrices.','Recover a parameter under two singularity constraints.','Classify all singular parameters for every value of a second parameter.'],
'line-intersection':['Solve two linear equations.','Explain why two matching coordinates are insufficient.','Solve and verify an intersection.','Determine whether two lines from point data intersect.','Reconstruct parameters for a prescribed intersection constraint.','Classify intersections for all parameter values, including coincident and parallel cases.'],
'unit-vector':['Evaluate a three-dimensional magnitude.','Diagnose incorrect normalization.','Normalize a nonzero vector and check its length.','Combine displacements and normalization to construct a point.','Recover a vector from a unit direction and a coordinate constraint.','Classify all unit vectors satisfying two projection constraints, including tangent and impossible cases.']}

def make(path,l,v):
 if path not in PATHS or l not in LEVELS or v not in (1,2,3):raise ValueError('Unknown pathway cell')
 a=v+1;b=a+1;c=b+1
 if path=='matrix-conformability':
  if l==1:
   f=[a,b];qn=f'A rectangular array has {a} rows and {b} entries in each row. State its matrix order.';ans=f'${a}\\times {b}$.';steps=[f'The order lists the number of rows first, then columns: {ans}'];hints=['Count rows before columns.','The order is not the total number of entries.'];mistake='Reversing rows and columns.'
  elif l==2:
   f=[False,True,a,a];qn=f'A has order {a} by {b}, B has order {b} by {a}. A student says A+B and AB are both impossible because the orders differ. Explain and state the order of any valid result.';ans=f'A+B is undefined; AB is {a} by {a}.';steps=['Addition requires identical orders; the orders here differ.',f'Multiplication requires the inner dimensions to match: both are {b}. The outer dimensions give {a} by {a}.'];hints=['Addition and multiplication have different conditions.','Compare the columns of A with the rows of B.'];mistake='Applying the addition rule to multiplication.'
  elif l==3:
   f=[True,a,c,False,False];qn=f'A is {a} by {b}, B is {b} by {c}. Decide whether AB, BA and A+B are defined. Give the order of every defined result.';ans=f'AB: {a} by {c}; BA and A+B undefined.';steps=[f'For AB the inner dimensions match ({b}), giving {a} by {c}.',f'For BA the inner dimensions {c} and {a} differ, so it is undefined.', 'Addition requires equal orders, which do not match.'];hints=['Write the orders in the proposed multiplication order.','Only matching inner dimensions allow multiplication.'];mistake='Assuming that if AB exists then BA exists.'
  elif l==4:
   f=[b,c,a,c,a,a];qn=f'A has order {a} by {b}; C has order {c} by {a}. B is unknown. The product ABC must exist and AB must have {c} columns. Find the orders of B, AB and ABC.';ans=f'B: {b} by {c}; AB: {a} by {c}; ABC: {a} by {a}.';steps=[f'For AB to exist, B must have {b} rows.',f'The columns of AB are exactly the columns of B, so B has {c} columns. This also matches the rows of C.',f'AB has order {a} by {c}; multiplying by C gives {a} by {a}.'];hints=['Determine B from AB first.','Then verify the second multiplication.'];mistake='Using the outer dimensions to test compatibility.'
  elif l==5:
   f=[b,c,b,b,False];qn=f'A is {a} by {b}, B is unknown, and AB exists with {a*c} entries. A third matrix C has {c} rows and {b} columns. Determine the order of B, and decide whether BC and BA exist. Give the order of each defined product.';ans=f'B is {b} by {c}; BC is {b} by {b}; BA undefined.';steps=[f'The existence of AB forces B to have {b} rows. Since AB has {a} rows and {a*c} entries, it has {c} columns.',f'B therefore has {c} columns, matching the rows of C. BC has order {b} by {b}.',f'BA would require {c}={a}, which is false.'];hints=['Divide the number of entries by the known number of rows.','Test both subsequent products separately.'];mistake='Inferring a product shape without checking the inner dimensions.'
  else:
   N=a*b if v!=2 else b*b; pairs=[(i,N//i) for i in range(1,N+1) if N%i==0 and i!=N//i];f=[M([[i,i,j,j] for i,j in pairs]),len(pairs)];pairs_text=', '.join(f'({i},{i},{j},{j})' for i,j in pairs);qn=f'For positive integers p,q,r,s, A has order p by q, B order q by r, C order r by s. Require AB+BC to exist and contain exactly {N} entries, but require BA to be undefined. Classify all possible ordered quadruples (p,q,r,s) and prove completeness.';ans=f'{pairs_text}.';steps=['AB has order p by r; BC has order q by s. Their sum exists exactly when p=q and r=s.',f'The result has pr={N} entries. BA would exist exactly when r=p, so exclude equal factors.',f'Enumerate every positive divisor p of {N}, put r={N}/p, and retain p different from r. This gives {pairs_text}.', 'Each listed quadruple meets the equal-order condition and entry count while making BA undefined. Every admissible quadruple must occur in this divisor enumeration.'];hints=['First derive the two equalities imposed by addition.','Use positive factor pairs, then exclude any equal pair.'];mistake='Matching the number of entries rather than the dimensions, or forgetting reversed factor pairs.'
 elif path=='singular-condition':
  A=M([[k,a],[b,k]]);root=s.sqrt(a*b)
  if l==1:
   f=[-a,b];qn=f'Solve $(x+{a})(x-{b})=0$ over the reals.';ans=f'$x=-{a}$ or $x={b}$.';steps=['A product is zero exactly when at least one factor vanishes.',f'Solve each linear factor to obtain {ans}'];hints=['Use the zero-product rule.','Retain both roots.'];mistake='Equating the factors instead of setting them to zero.'
  elif l==2:
   B=M([[a,b],[2*a,2*b]]);f=[0,True];qn=f'A student claims {L(B)} is invertible because all entries are nonzero. Explain why this fails and state its determinant.';ans='Singular; determinant 0.';steps=['The second row is twice the first, so the rows are dependent.',f'The determinant is ${a}({2*b})-{b}({2*a})=0$, which prevents inversion.'];hints=['Compare the two rows.','Nonzero entries are not an invertibility test.'];mistake='Confusing nonzero entries with a nonzero determinant.'
  elif l==3:
   f=[-root,root];qn=f'Find every real k for which {L(A)} is singular.';ans=f'$k=\\pm {s.latex(root)}$.';steps=[f'The determinant is $k^2-{a*b}$.',f'Set it equal to zero to obtain $k^2={a*b}$, so {ans}'];hints=['A square matrix is singular iff its determinant is zero.','Take both square roots.'];mistake='Keeping only the positive root.'
  elif l==4:
   B=M([[k-a,0],[1,k+b]]);f=[-b,a,-root,root];qn=f'Let A={L(A)} and B={L(B)}. Find every real k making AB singular and identify which factor is singular at each value.';ans=f'B: $k=-{b},{a}$; A: $k=\\pm {s.latex(root)}$; four distinct values.';steps=[f'$\\det(AB)=\\det A\\det B=(k^2-{a*b})(k-{a})(k+{b})$.',f'The first factor gives $k=\\pm {s.latex(root)}$; the second and third give $k={a},-{b}$.',f'Since {a}< {s.latex(root)} <{b} (by squaring), none coincide; at each root exactly one factor is singular.'];hints=['Use the determinant of a product.','Check for duplicate parameter values.'];mistake='Requiring both factors to be singular rather than at least one.'
  elif l==5:
   B=M([[k,h],[1,k]]);C=M([[k-a,0],[1,k+b]]);f=[-b,b*b,a,a*a];qn=f'The matrices {L(B)} and {L(C)} are both singular. Determine every real pair (k,h), and verify both determinants.';ans=f'$(k,h)=(-{b},{b*b})$ or $({a},{a*a})$.';steps=[f'The second determinant is $(k-{a})(k+{b})$, hence k={a} or k=-{b}.','The first determinant is k squared minus h, so h must equal k squared.',f'Both stated pairs make each determinant zero; no other k is possible.'];hints=['Start with the matrix containing only k.','Use the second unknown to enforce the remaining determinant.'];mistake='Finding the singular values of k but not determining h.'
  else:
   b=2*a+1;B=M([[k-a,h],[1,k-b]]);crit=-s.Rational((b-a)**2,4);mid=s.Rational(a+b,2);disc=(a-b)**2+4*h;f=[s.expand(B.det()),crit,mid,0,1,2];qn=f'For every real h, classify all real k for which {L(B)} is singular. Give the roots explicitly when they exist, and prove the threshold case.';ans=f'No real k if $h<{s.latex(crit)}$; one at equality, $k={s.latex(mid)}$; two if $h>{s.latex(crit)}$, namely $k=({a+b}\\pm\\sqrt{{{(a-b)**2}+4h}})/2$.';steps=[f'Singularity is equivalent to $(k-{a})(k-{b})-h=0$, a monic quadratic.',f'Completing the square gives $(k-{s.latex(mid)})^2=h+{s.latex(-crit)}$.',f'The right side is negative, zero or positive according as h is below, equal to or above {L(crit)}. This gives 0, 1 or 2 distinct real roots.',f'Taking the two square roots yields {ans} Since the determinant condition is equivalent, there are no extraneous solutions.'];hints=['Form the determinant before treating h as a parameter.','Complete the square or use the discriminant.'];mistake='Reporting two roots at the threshold or ignoring parameter ranges.'
 elif path=='line-intersection':
  P=M([a,0,0]);d=M([1,b,1]);Q=M([0,b*a,a]);e=M([1,0,0]);hit=M([2*a,b*a,a]);
  if l==1:
   f=[a,2*a];qn=f'Solve $u-t={a}$ and $t={a}$ simultaneously.';ans=f'$t={a}, u={2*a}$.';steps=[f'Substitute t={a} into the first equation.',f'This gives u={2*a}.'];hints=['One parameter is already known.','Substitute it into the remaining equation.'];mistake='Using the wrong sign when rearranging u-t.'
  elif l==2:
   f=[False,a];qn=f'Two points on separate lines have coordinates (1,{a},0) and (1,{a},{a}). A student says they are the same point because x and y agree. Explain the error and give their separation.';ans=f'Not equal; separation {a}.';steps=['Equality in three dimensions requires all three coordinates to match.',f'The difference is solely along z and has magnitude {a}.'];hints=['Compare every coordinate.','Only one coordinate difference is nonzero.'];mistake='Checking only two coordinates of a 3D intersection.'
  elif l==3:
   f=[a,2*a,hit];qn=f'Find the intersection of $\\mathbf r={L(P)[1:-1]}+t{L(d)[1:-1]}$ and $\\mathbf r={L(Q)[1:-1]}+u{L(e)[1:-1]}$. Give both parameters and verify all coordinates.';ans=f'$t={a},u={2*a}$; {L(hit)}.';steps=[f'Equating z gives t={a}; the y equality is then satisfied.',f'Equating x gives u={a}+t={2*a}.',f'Substituting both values yields the same point {L(hit)}.'];hints=['Choose a coordinate equation involving only one parameter.','Verify the unused coordinate equation.'];mistake='Solving two equations without verifying the third.'
  elif l==4:
   Q2=M([0,b*a,a+1]);f=[False,a+1,b];qn=f'Line L passes through {L(P)} and {L(P+d)}. Line K passes through {L(Q2)} and {L(Q2+e)}. Decide if they intersect; if not, justify whether they are skew or parallel.';ans=f'Skew. The z equation forces t={a+1}; the y coordinates then differ by {b}.';steps=[f'Subtract the points to obtain directions {L(d)} and {L(e)}, which are not proportional.',f'Equating z forces t={a+1}, giving y={b*(a+1)} on L but y={b*a} on K.',f'The contradiction of size {b} excludes intersection; nonparallel disjoint lines are skew.'];hints=['Construct directions from point differences.','Check the coordinate that has not been used.'];mistake='Calling every non-intersecting pair parallel.'
  elif l==5:
   f=[a,b*a,2*a,hit];qn=f'L is $\\mathbf r={L(P)[1:-1]}+t{L(d)[1:-1]}$. K is $\\mathbf r=(0,h,{a})+u(1,0,0)$. Find the unique h for which they intersect, the intersection and both parameters.';ans=f'$t={a},h={b*a},u={2*a}$; {L(hit)}.';steps=[f'The z coordinate forces t={a}.',f'The y equation then forces h={b*a}.',f'The x equation gives u={2*a}; both lines give {L(hit)}, proving existence and uniqueness.'];hints=['The fixed z coordinate determines t.','Use y to recover h, then solve for u.'];mistake='Finding h without verifying the actual intersection.'
  else:
   f=[-a/k,-a/k,h,0];qn=f'For all real k,h consider $L:(t,0,0)$ and $K:(u,{a}+ku,h)$. Classify them as parallel distinct, intersecting or skew, giving every intersection parameter pair where it exists. Then repeat the classification if the constant {a} in K is replaced by 0, including coincident lines. Prove completeness.';ans=f'Original: k=0 parallel distinct; k nonzero and h=0 intersect at t=u=-{a}/k; k nonzero and h nonzero skew. Replaced: k=0,h=0 coincident (all t=u); k=0,h nonzero parallel distinct; k nonzero,h=0 intersect at t=u=0; otherwise skew.';steps=['The direction vectors are (1,0,0) and (1,k,0); they are parallel exactly when k=0.','Intersection requires simultaneously t=u, second coordinate of K zero, and h=0.',f'For the original constant {a} nonzero, k=0 never permits an intersection. For k nonzero, u=-{a}/k is forced, and h=0 is necessary and sufficient.', 'With the constant replaced by zero, k=0 and h=0 makes the two sets identical; k=0 and h nonzero makes them parallel distinct. For k nonzero the only candidate is t=u=0, valid exactly when h=0. The remaining nonparallel disjoint cases are skew.'];hints=['Test direction proportionality before dividing by k.','Treat h=0 and the replaced constant separately.'];mistake='Dividing by k before considering parallel or coincident lines.'
 elif path=='unit-vector':
  D=M([a,b,0]);n=s.sqrt(a*a+b*b);U=D/n
  if l==1:
   f=[s.sqrt(a*a+b*b+c*c)];qn=f'Calculate the magnitude of the vector ({a},{b},{c}).';ans=L(f[0]);steps=[f'Sum the squared components to obtain {a*a+b*b+c*c}, then take its positive square root {ans}.'];hints=['Use all three squared components.','Magnitude is nonnegative.'];mistake='Omitting the third component.'
  elif l==2:
   f=[n/(a+b),U];qn=f'A student normalizes ({a},{b},0) by dividing by {a+b}. Explain why this fails, give the magnitude of their result and correct the vector.';ans=f'Proposed magnitude {L(n/(a+b))}; correct unit vector {L(U)}.';steps=[f'The length of the input is {L(n)}, not the sum of its components.',f'The proposed vector has length {L(n/(a+b))}, not 1.',f'Dividing by the true length yields {L(U)}.'];hints=['Test the length of the proposed vector.','Divide by the Euclidean magnitude.'];mistake='Using the sum of coordinates as the norm.'
  elif l==3:
   E=M([a,-b,c]);U3=E/E.norm();f=[U3,1];qn=f'Find the unit vector in the direction of {L(E)} and verify that its magnitude is one.';ans=L(U3);steps=[f'The magnitude is {L(E.norm())}.',f'Divide every component by this positive number to get {ans}.', 'The squared length is the original squared length divided by itself, which equals 1.'];hints=['Preserve the signs of the direction components.','Divide by the positive length.'];mistake='Changing the direction by taking absolute values componentwise.'
  elif l==4:
   P=M([1,2,3]);Q=P+D;R=P+2*n*U;f=[U,R];qn=f'P={L(P)}, Q={L(Q)}. Find the unit vector from P towards Q and the point R at distance {L(2*n)} from P on the ray through Q.';ans=f'{L(U)}; R={L(R)}.';steps=[f'Compute Q-P={L(D)} and normalize to obtain {L(U)}.',f'Move from P by the stated distance times the unit direction: $R=P+{s.latex(2*n)}\\mathbf u={L(R)[1:-1]}$.', 'The multiplier is positive, so R is on the required ray, not its opposite.'];hints=['Subtract the points in the direction of travel.','Multiply the unit direction by the required distance.'];mistake='Moving from the origin instead of P.'
  elif l==5:
   E=M([a,b,c]);ue=E/E.norm();F=2*E;f=[2*E.norm(),F];qn=f'A vector has unit direction {L(ue)} and its third component is {2*c}. Recover the original vector and its magnitude, proving uniqueness.';ans=f'{L(F)}; magnitude {L(2*E.norm())}.';steps=['A vector with a specified unit direction equals a positive scalar times that unit vector.',f'The third component is nonzero, so matching it uniquely gives the positive scalar {L(2*E.norm())}.',f'Multiplying gives {L(F)}. Its magnitude is the scalar, confirming the direction.'];hints=['Write the unknown as a positive multiple of its unit direction.','Use the nonzero third coordinate.'];mistake='Allowing a negative multiple, which reverses the unit direction.'
  else:
   # Constraints u dot (1,0,0)=h, u dot (0,a,0)=k; normalize residual.
   f=[1-h*h-k*k/a**2,0,1,2];qn=f'For every real h,k, find all unit vectors w satisfying $\\mathbf w\\cdot(1,0,0)=h$ and $\\mathbf w\\cdot(0,{a},0)=k$. Classify the number of solutions over the entire (h,k) plane and prove the boundary case.';ans=f'Let $R=1-h^2-k^2/{a*a}$. If R<0: none; R=0: one $(h,k/{a},0)$; R>0: two $(h,k/{a},\\pm\\sqrt R)$.';steps=[f'The scalar-product constraints force the first two components to be h and k/{a}.','The unit condition is the sum of the three squared components equal to one.',f'Thus the remaining component satisfies $z^2=1-h^2-k^2/{a*a}$. This is negative outside the ellipse, zero on it, positive inside it.',f'The listed vectors all satisfy both projections and the unit condition. Every solution must have these first two components, so the list is exhaustive.'];hints=['Read the first two components from the projection equations.','Use the unit condition to classify the remaining component.'];mistake='Forgetting the negative branch or allowing an imaginary component in a real vector.'
 else:raise AssertionError(path)
 def encode(v):
  if isinstance(v,bool):return v
  if isinstance(v,s.MatrixBase):return {'matrix':[[str(e) for e in row] for row in v.tolist()]}
  return str(v)
 return dict(path=path,focus_skill=PATHS[path],tier=l,variant=v,assessment_role='prerequisite_bridge' if l==1 else 'concept_diagnostic' if l==2 else 'direct_focus_task',question_latex=qn,final_answer_latex=ans,worked_solution_latex=steps,progressive_hints=hints,rubric=[dict(marks=1,criterion=p) for p in steps],facts=[encode(e) for e in f],likely_mistake=mistake,origin='original',examination_source=None,difficulty_status='editorial_design_teacher_pending',demand_rationale=RATIONALES[path][l-1])
